mapper.select:
SELECT T.* FROM (SELECT A.*, D.TESTNAME, C.METHODNAME, C.TESTMETHODBASIS, MV.TRIALSCOPE, B.METHODID, B.TESTCATEGORYID, B.TESTMETHODTYPE, B.TESTCLASS, B.ACTIVATEDFLAG AS SHOWFLAG, M.DEFAULTFLAG, M.ORGID FROM T_EMC_CAPACITY_ITEM_GROUP A LEFT JOIN T_EMC_TEST_CAPACITY M ON A.TESTCAPACITYID = M.ID LEFT JOIN T_EMC_TEST_METHOD B ON M.TESTMETHODID = B.ID LEFT JOIN T_EMC_METHOD C ON B.METHODID = C.ID LEFT JOIN T_EMC_METHOD_VERSION MV ON C.MAXVERSIONID = MV.ID LEFT JOIN T_EMC_TEST D ON B.TESTID = D.ID WHERE B.ACTIVATEDFLAG = '1') T
AND NOT EXISTS (SELECT 1 FROM ${targetTable} TAR_ WHERE TAR_.${targetItemGroupIdColumn} = T.ID
AND TAR_.${targetFilterColumn} = #{targetFilterValue}
AND TAR_.${targetFilterColumn1} = #{targetFilterValue1}
)
ORDER BY
T.ID DESC

SELECT T.*
  FROM T_EMC_CAPACITY_ITEM_GROUP T
 WHERE T.ID = #{id}
